def parse_ts(obj):
    for k in ("timestamp","createdAt","created_at","time"):
        v=obj.get(k) if isinstance(obj,dict) else None
        if v: 
            try:
                if isinstance(v,(int,float)):
                    # ms or s
                    if v>1e12: return datetime.fromtimestamp(v/1000, tz=timezone.utc).astimezone(CST)
                    return datetime.fromtimestamp(v, tz=timezone.utc).astimezone(CST)
                s=str(v).replace("Z","+00:00")
                dt=datetime.fromisoformat(s)
